-- The centre point of each zip code, so a company can describe part of its
-- service area as "within so many miles of here" and have it stored as the
-- zip codes that fall inside. The distance is measured between centre
-- points, which is as exact as a zip code is.
--
-- Source: U.S. Census Bureau, 2023 ZCTA gazetteer file (2020 ZCTAs)
--   https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2023_Gazetteer/2023_Gaz_zcta_national.zip
-- retrieved 2026-10-10, for the zips zip_county lists (Pennsylvania), with
-- packages/db/scripts/gen_zip_centroid.py. `lat` and `lng` are the ZCTA's
-- internal point, in degrees. (The 2020 edition of the file lacks 53 of them.)

CREATE TABLE zip_centroid (
  zip text PRIMARY KEY CHECK (zip ~ '^[0-9]{5}$'),
  lat double precision NOT NULL CHECK (lat BETWEEN -90 AND 90),
  lng double precision NOT NULL CHECK (lng BETWEEN -180 AND 180)
);

-- Global reference data like zip_county: no RLS, readable by the Lambdas.
GRANT SELECT ON zip_centroid TO app_rw;

